// def __init__(self, name: str) -> None:
//     self.name = name
inline Animal::Animal(std::string_view name) : name(name) {}

// def __init__(self) -> None:
//     self.lives = 9
inline Cat::Cat() : lives(9) {}

// def __init__(self, wings: int32) -> None:
//     self.wings = wings
inline Bird::Bird(int32_t wings) : wings(wings) {}

// def __init__(self) -> None:
//     self.span = 3
inline Bat::Bat() : span(3) {}

// def __init__(self, tag: str) -> None:
//     self.tag = tag
inline Truth::Truth(std::string_view tag) : tag(tag) {}

// def __bool__(self) -> bool:
//     calls.append(self.tag)
//     return True
inline bool Truth::__bool__() const {
    calls->push_back(this->tag);
    return true;
}

// def __init__(self) -> None:
//     self.n = 0
inline AnyEq::AnyEq() : n(0) {}

// def __eq__(self, other: int32) -> bool:
//     return True
inline bool AnyEq::__eq__(int32_t other) const {
    return true;
}

// # constructor: decided in `__init__`.
// def __init__(self, a: Dog) -> None:
//     if isinstance(a, Cat):
//         self.v = a.lives  # tpyc: ok
//     self.v = 1
inline Ctor::Ctor(const Dog& a) {
    if (false) {
    }
    this->v = 1;
}

// def __enter__(self) -> "Guard":
//     return self
inline Guard& Guard::__enter__() {
    return (*this);
}

// def __exit__(self, kind: None, value: None, tb: None) -> None:
//     pass
inline void Guard::__exit__(std::monostate kind, std::monostate value, std::monostate tb) const {
}

// def __init__(self) -> None:
//     self.items = []
inline Bag::Bag() : items(std::vector<int32_t>{}) {}

// def add(self, v: int32) -> None:
//     self.items.append(v)
inline void Bag::add(int32_t v) {
    this->items.push_back(v);
}

// def __init__(self, tag: str, val: bool) -> None:
//     self.tag = tag
//     self.val = val
inline Gate::Gate(std::string_view tag, bool val)
    : tag(tag),
      val(val) {}

// def __bool__(self) -> bool:
//     calls.append(self.tag)
//     return self.val
inline bool Gate::__bool__() const {
    calls->push_back(this->tag);
    return this->val;
}

// def __init__(self) -> None:
//     self.n = 0
inline Pouch::Pouch() : n(0) {}

// def __len__(self) -> int32:
//     calls.append("len")
//     return self.n
inline int32_t Pouch::__len__() const {
    calls->push_back("len");
    return this->n;
}

inline size_t Pouch::size() const {
    auto len = __len__();
    if (len < 0) ::tpy::raise<::tpy::ValueError>("__len__() should return >= 0");
    return static_cast<size_t>(len);
}

// def __init__(self, n: int32) -> None:
//     self.n = n
//     if False:
//         global shadowed
//     shadowed = n  # tpyc: ok
inline DeclCtor::DeclCtor(int32_t n) : n(n) {
    if (false) {
    }
    shadowed = n;
}

